const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const YEARS = [2015, 2021];
    const SCALE = 1000;

    // Fetch Sakha region from GAUL level1 (admin-1)
    let gaul1 = ee.FeatureCollection('FAO/GAUL/2015/level1');
    let sakhaFC = gaul1
      .filter(ee.Filter.eq('ADM0_NAME', 'Russian Federation'))
      .filter(ee.Filter.or(
        ee.Filter.stringContains('ADM1_NAME', 'Sakha'),
        ee.Filter.stringContains('ADM1_NAME', 'Yakut')
      ));
    let sakhaCount = await sakhaFC.size().getInfo();

    // Fallback to simplified GAUL if needed
    if (!sakhaCount || sakhaCount === 0) {
      let gaul1s = ee.FeatureCollection('FAO/GAUL_SIMPLIFIED_500m/2015/level1');
      sakhaFC = gaul1s
        .filter(ee.Filter.eq('ADM0_NAME', 'Russian Federation'))
        .filter(ee.Filter.or(
          ee.Filter.stringContains('ADM1_NAME', 'Sakha'),
          ee.Filter.stringContains('ADM1_NAME', 'Yakut')
        ));
      sakhaCount = await sakhaFC.size().getInfo();
    }

    if (!sakhaCount || sakhaCount === 0) {
      console.log('Region match failed for Sakha (GAUL L1).');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    const region = ee.FeatureCollection(sakhaFC).union(1).geometry();

    // Hansen forest dataset
    const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');
    const tree = hansen.select('treecover2000');
    const lossyear = hansen.select('lossyear');

    function forestMaskForYear(y) {
      const initialForest = tree.gte(30)
        .and(lossyear.eq(0).or(lossyear.gte(y - 2000)));
      return initialForest.rename('forest').updateMask(initialForest);
    }

    async function burnedStatsForYear(y) {
      const start = ee.Date.fromYMD(y, 1, 1);
      const end = ee.Date.fromYMD(y, 12, 31);

      let col = ee.ImageCollection('MODIS/061/MCD64A1')
        .filterDate(start, end)
        .filterBounds(region)
        .select('BurnDate');
      let csize = await col.size().getInfo();
      if (!csize || csize === 0) {
        col = ee.ImageCollection('MODIS/006/MCD64A1')
          .filterDate(start, end)
          .filterBounds(region)
          .select('BurnDate');
        csize = await col.size().getInfo();
      }
      if (!csize || csize === 0) {
        return { year: y, colSize: 0, status: 'C1' };
      }

      const burned = col.map(img => img.gt(0)).max().rename('burned');
      const forest = forestMaskForYear(y).clip(region);

      // Forest validity check
      const fCount = ee.Number(forest.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: SCALE,
        maxPixels: 1e13,
        tileScale: 2
      }).get('forest'));
      const forestArea = ee.Image.pixelArea().rename('area').updateMask(forest);
      const fAreaM2 = ee.Number(forestArea.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: SCALE,
        maxPixels: 1e13,
        tileScale: 2
      }).get('area'));

      const burnedForest = burned.updateMask(burned).updateMask(forest).rename('burnedForest');
      const bCount = ee.Number(burnedForest.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: SCALE,
        maxPixels: 1e13,
        tileScale: 2
      }).get('burnedForest'));
      const bAreaM2 = ee.Number(ee.Image.pixelArea().rename('area').updateMask(burnedForest).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: SCALE,
        maxPixels: 1e13,
        tileScale: 2
      }).get('area'));

      const results = {
        year: y,
        colSize: csize,
        forestCount: await fCount.getInfo(),
        forestAreaKm2: (await fAreaM2.getInfo()) ? (await fAreaM2.getInfo()) / 1e6 : null,
        burnedCount: await bCount.getInfo(),
        burnedAreaKm2: (await bAreaM2.getInfo()) ? (await bAreaM2.getInfo()) / 1e6 : null
      };
      return results;
    }

    console.log(`Region match (GAUL L1): ${sakhaCount} feature(s).`);

    const r2015 = await burnedStatsForYear(2015);
    const r2021 = await burnedStatsForYear(2021);

    // Handle collection availability
    if (r2015.status === 'C1' || r2021.status === 'C1') {
      console.log(`MCD64A1 Images — 2015: ${r2015.colSize || 0} | 2021: ${r2021.colSize || 0}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    console.log(`MCD64A1 Images — 2015: ${r2015.colSize} | 2021: ${r2021.colSize}`);

    // Valid pixel check (forest baseline must exist)
    if (!r2015.forestCount || r2015.forestCount === 0 || !r2021.forestCount || r2021.forestCount === 0) {
      console.log(`Forest px — 2015: ${r2015.forestCount || 0} | 2021: ${r2021.forestCount || 0}`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }

    // Calculation validity
    if (
      r2015.forestAreaKm2 == null || r2021.forestAreaKm2 == null ||
      r2015.burnedAreaKm2 == null || r2021.burnedAreaKm2 == null ||
      !isFinite(r2015.forestAreaKm2) || !isFinite(r2021.forestAreaKm2) ||
      !isFinite(r2015.burnedAreaKm2) || !isFinite(r2021.burnedAreaKm2)
    ) {
      console.log('C3: Calculation Failure (Result is None/NaN/invalid).');
      return;
    }

    const fAreaAvgKm2 = (r2015.forestAreaKm2 + r2021.forestAreaKm2) / 2.0;
    console.log(`Forest px — 2015: ${r2015.forestCount} | 2021: ${r2021.forestCount}`);
    console.log(`Forest area (km²) — 2015: ${r2015.forestAreaKm2.toFixed(0)} | 2021: ${r2021.forestAreaKm2.toFixed(0)}`);

    const pct2015 = (r2015.burnedAreaKm2 / (r2015.forestAreaKm2 || fAreaAvgKm2)) * 100.0;
    const pct2021 = (r2021.burnedAreaKm2 / (r2021.forestAreaKm2 || fAreaAvgKm2)) * 100.0;

    console.log(`2015 burned forest — px: ${r2015.burnedCount} | area_km²: ${r2015.burnedAreaKm2.toFixed(0)} | %forest: ${pct2015.toFixed(3)}`);
    console.log(`2021 burned forest — px: ${r2021.burnedCount} | area_km²: ${r2021.burnedAreaKm2.toFixed(0)} | %forest: ${pct2021.toFixed(3)}`);

    // Final answer
    if (r2015.burnedAreaKm2 > r2021.burnedAreaKm2) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
